import json, math
for s in ['{"a":NaN}','{"a":Infinity}','{"a":1e400}','{"a":1e-400}','{"a":12345678901234567890123456789012345678901234567890}']:
    try:
        print(repr(s), '->', json.loads(s))
    except Exception as e:
        print(repr(s), '-> ERR', type(e).__name__, e)
print(json.loads('{"a":1,"a":2}'))
try:
    json.loads('['*200000)
except Exception as e:
    print('deep:', type(e).__name__)
try:
    json.loads('\ufeff{}')
except Exception as e:
    print('bom str:', type(e).__name__, e)
